from pathlib import Path

path = Path('tools/build-old-world-map-batch.py')
text = path.read_text()

old = """    builder = load_builder()\n    if args.batch != 'maritime-oceania':\n        builder.PACIFIC_EXTRAS = []\n\n    batch_mask = builder.map_v2.repair(unary_union([bbox_geometry(z) for z in zones]))\n    admin0 = builder.fast.fetch_json_retry(builder.map_v2.ADMIN0_URL)\n    original_targets = builder.target_admin0_features(admin0, set(plan['targetContinents']))\n    targets = []\n    for feature, geom in original_targets:\n        clipped = builder.map_v2.repair(geom.intersection(batch_mask))\n        if not clipped.is_empty and builder.map_v2.area_sqkm(clipped) >= 8:\n            targets.append((feature, clipped))\n    wanted_mask = builder.target_mask(targets)\n\n    geo = json.loads(builder.BASE_GEO.read_text())\n    meta_doc = json.loads(builder.BASE_META.read_text())\n    resources = json.loads(builder.BASE_RESOURCES.read_text())\n    base_count = len(geo.get('features', []))\n\n    existing_geoms = [builder.map_v2.repair(shape(f['geometry'])) for f in geo['features']]\n    existing_tree = STRtree(existing_geoms)\n    builder.fast.prepare_existing_index(geo['features'])\n\n    print(f'BATCH={args.batch}', flush=True)\n    print('BATCH_ZONES=' + ','.join(z['id'] for z in zones), flush=True)\n    print(f'PHASE setup seconds={time.perf_counter()-started:.2f}', flush=True)\n"""

new = """    print(f'BATCH={args.batch}', flush=True)\n    print('BATCH_ZONES=' + ','.join(z['id'] for z in zones), flush=True)\n\n    phase = time.perf_counter()\n    builder = load_builder()\n    if args.batch != 'maritime-oceania':\n        builder.PACIFIC_EXTRAS = []\n    print(f'PHASE builder_import seconds={time.perf_counter()-phase:.2f}', flush=True)\n\n    phase = time.perf_counter()\n    batch_mask = builder.map_v2.repair(unary_union([bbox_geometry(z) for z in zones]))\n    print(f'PHASE batch_mask seconds={time.perf_counter()-phase:.2f}', flush=True)\n\n    # Fetch ADM0 once with a short bounded timeout. Filter by raw continent/name\n    # before constructing or repairing geometries, then pass only plausible batch\n    # candidates through the normal target filter. This avoids cleaning every\n    # Old World polygon for every geographic batch.\n    phase = time.perf_counter()\n    admin0 = builder.fast.fetch_json_retry(builder.map_v2.ADMIN0_URL, attempts=2, timeout=30)\n    print(f'PHASE admin0_fetch seconds={time.perf_counter()-phase:.2f}', flush=True)\n\n    phase = time.perf_counter()\n    selected = []\n    target_continents = set(plan['targetContinents'])\n    batch_bounds = batch_mask.bounds\n    for feature in admin0.get('features', []):\n        if builder.continent(feature) not in target_continents and not builder.is_greenland(feature):\n            continue\n        raw = shape(feature['geometry'])\n        minx, miny, maxx, maxy = raw.bounds\n        bminx, bminy, bmaxx, bmaxy = batch_bounds\n        # Dateline-crossing Pacific batches are allowed through by latitude;\n        # all other batches use a cheap envelope rejection first.\n        dateline_batch = any(z['bbox'][0] > z['bbox'][2] for z in zones)\n        if maxy < bminy or miny > bmaxy:\n            continue\n        if not dateline_batch and (maxx < bminx or minx > bmaxx):\n            continue\n        selected.append(feature)\n    original_targets = builder.target_admin0_features({'type':'FeatureCollection','features':selected}, target_continents)\n    targets = []\n    for feature, geom in original_targets:\n        clipped = builder.map_v2.repair(geom.intersection(batch_mask))\n        if not clipped.is_empty and builder.map_v2.area_sqkm(clipped) >= 8:\n            targets.append((feature, clipped))\n    wanted_mask = builder.target_mask(targets)\n    print(f'PHASE target_selection seconds={time.perf_counter()-phase:.2f} countries={len(targets)}', flush=True)\n\n    phase = time.perf_counter()\n    geo = json.loads(builder.BASE_GEO.read_text())\n    meta_doc = json.loads(builder.BASE_META.read_text())\n    resources = json.loads(builder.BASE_RESOURCES.read_text())\n    base_count = len(geo.get('features', []))\n    existing_geoms = [builder.map_v2.repair(shape(f['geometry'])) for f in geo['features']]\n    existing_tree = STRtree(existing_geoms)\n    # Do not build fast.py's second global spatial index: this batch runner has\n    # its own STRtree and all clipping is handled through local_subtract().\n    print(f'PHASE existing_index seconds={time.perf_counter()-phase:.2f} regions={base_count}', flush=True)\n    print(f'PHASE setup seconds={time.perf_counter()-started:.2f}', flush=True)\n"""

if new not in text:
    if old not in text:
        raise RuntimeError('Batch setup anchor not found')
    text = text.replace(old, new, 1)

path.write_text(text)
print('Old World batch performance fix applied')
